class ErrRuff(Exception):
    """Base class for exceptions related to RUFF"""
    pass


class ErrRuffError(ErrRuff):
    """generic RUFF error"""

    def __init__(self, err_data):
        """Initialize err"""
        super(ErrRuffError, self).__init__(str(err_data))
        self.err = err_data


class ErrRuffBlockingError(ErrRuffError):
    """can't reach the point where we can give PASS/FAIL verdict on tested functionality"""
    pass


class ErrRuffFailError(ErrRuffError):
    """tested functionality detected to work incorrectly"""
    pass


class ErrRuffFailedFinishingHandler(ErrRuffError):
    """await_finish method returned 0"""
    pass


class ErrRuffEventNotOccurred(ErrRuffError):
    """message status is timeout"""
    pass


class ErrRuffEventOccurred(ErrRuffError):
    """message status is success"""
    pass


class ErrRuffEventOccurredButParsingFailed(ErrRuffError):
    """message status is failure"""
    pass


class ErrRuffNoSuchCommand(ErrRuffError):
    def __init__(self, device_name, cmd_name):
        """Initialize err"""
        err_msg = "device '%s' has no command named '%s'" % (device_name, cmd_name)
        super(ErrRuffNoSuchCommand, self).__init__(err_msg)


class ErrRuff4RobotAlreadyExists(ErrRuffError):
    def __init__(self, old_params, new_params):
        """Initialize err"""
        self.old_params = old_params
        self.new_params = new_params

        super(ErrRuff4RobotAlreadyExists, self).__init__(str(self))

    def __str__(self):
        err_msg = "You try to initialize Ruff4Robot one more time with (%s) \
                  while it already exists with (%s)" % (str(self.new_params), str(self.old_params))
        return err_msg


class ErrRuffCommandError(ErrRuffError):
    def __init__(self, device_name, cmd):
        """Initialize err"""
        self.device_name = device_name
        self.cmd = cmd
        err_msg = "device '%s' command '%s'" % (device_name, cmd)
        super(ErrRuffCommandError, self).__init__(err_msg)


class ErrRuffCommandNotStarted(ErrRuffCommandError):
    pass


class ErrRuffCommandFailed(ErrRuffCommandError):
    pass


class ErrRuffCommandTimeouted(ErrRuffCommandError):
    pass


class ErrRuffCommandSucceeded(ErrRuffCommandError):
    pass


class ErrRuffDeviceRegistration(ErrRuffError):
    pass


class ErrRuffEnvConfigFilesGenerationFailed(ErrRuffError):
    def __init__(self, err_list):
        """Initialize err"""
        self.err_list = err_list
        err_msg = "Env configuration generation failed: '%s'" % self.err_list
        super(ErrRuffEnvConfigFilesGenerationFailed, self).__init__(err_msg)
